import React, { useState, useEffect, useRef } from 'react';
import Blobs from '../components/Blobs';
import Orb3D from '../components/Orb3D';

const PHASES = [
  { name:'Andas in',  seconds:4, colors:['#2040a0','#0c1848','#4060d0'], label:'Djupt in genom näsan' },
  { name:'Håll',      seconds:7, colors:['#705010','#2c1c04','#a07828'], label:'Håll andan stilla' },
  { name:'Andas ut',  seconds:8, colors:['#205040','#0c2018','#408068'], label:'Långsamt ut genom munnen' },
];
const TOTAL = 4;

export default function Breathing({ setPage }) {
  const [running, setRunning] = useState(false);
  const [done,    setDone]    = useState(false);
  const [phase,   setPhase]   = useState(0);
  const [count,   setCount]   = useState(0);
  const [cycle,   setCycle]   = useState(0);
  const timer = useRef(null);

  const runPhase = (pi, ci) => {
    if (ci >= TOTAL) { setRunning(false); setDone(true); return; }
    const p = PHASES[pi];
    setPhase(pi); setCycle(ci); setCount(p.seconds);
    let c = p.seconds;
    timer.current = setInterval(() => {
      c--;
      setCount(c);
      if (c <= 0) {
        clearInterval(timer.current);
        const np = (pi + 1) % PHASES.length;
        const nc = np === 0 ? ci + 1 : ci;
        setTimeout(() => runPhase(np, nc), 400);
      }
    }, 1000);
  };

  const start = () => { setRunning(true); setDone(false); runPhase(0, 0); };
  useEffect(() => () => clearInterval(timer.current), []);

  const cur = PHASES[phase];

  if (done) return (
    <div style={{ minHeight:'100vh', position:'relative', overflow:'hidden' }}>
      <Blobs variant="calm" />
      <div style={{ position:'absolute', top:'-20%', right:'-18%', zIndex:0, opacity:0.7, pointerEvents:'none', animation:'drift 14s ease-in-out infinite' }}>
        <Orb3D size={420} colors={['#204838','#0c1e14','#408060']} speed={0.15} />
      </div>
      <div style={{ position:'relative', zIndex:1, minHeight:'100vh', display:'flex', flexDirection:'column', justifyContent:'flex-end', padding:'80px 32px 52px', maxWidth:480, margin:'0 auto', animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both' }}>
        <h1 style={{ fontSize:'clamp(44px,10vw,72px)', fontWeight:700, letterSpacing:'-0.055em', lineHeight:0.88, color:'#fff', marginBottom:20 }}>
          BRA<br/><span style={{ color:'rgba(255,255,255,0.22)' }}>JOBBAT</span>
        </h1>
        <p style={{ fontSize:15, color:'rgba(255,255,255,0.4)', marginBottom:40, fontWeight:300, maxWidth:280 }}>Ditt nervsystem har lugnat ner sig. Du klarade 4 omgångar.</p>
        <div style={{ display:'flex', gap:10 }}>
          <button onClick={()=>setPage('checkin')} style={{ flex:1, padding:'14px', borderRadius:100, background:'rgba(255,255,255,0.9)', color:'#13121a', fontSize:13, fontWeight:600 }}>Checka in humöret</button>
          <button onClick={()=>{setDone(false);setRunning(false);}} className="glass" style={{ padding:'14px 20px', borderRadius:100, color:'rgba(255,255,255,0.55)', fontSize:13 }}>Igen</button>
        </div>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight:'100vh', position:'relative', overflow:'hidden' }}>
      <Blobs variant={running ? 'calm' : 'default'} />

      {/* The orb IS the breathing object — massive, fills most of screen */}
      <div style={{ position:'absolute', top:'50%', left:'50%', transform:'translate(-50%, -56%)', zIndex:0, pointerEvents:'none', transition:'transform 0.8s cubic-bezier(0.4,0,0.2,1)' }}>
        <div style={{
          transform: running
            ? phase === 0 ? 'scale(1.22)' : phase === 1 ? 'scale(1.22)' : 'scale(0.84)'
            : 'scale(1)',
          transition: running
            ? phase === 0 ? `transform ${PHASES[0].seconds * 0.85}s cubic-bezier(0.4,0,0.2,1)` 
            : phase === 1 ? 'transform 0.6s ease'
            : `transform ${PHASES[2].seconds * 0.85}s cubic-bezier(0.4,0,0.6,1)`
            : 'transform 1s ease',
        }}>
          <Orb3D
            size={340}
            colors={running ? cur.colors : ['#404060','#181828','#6060a0']}
            speed={running ? (phase === 1 ? 0.05 : 0.3) : 0.2}
          />
        </div>
      </div>

      {/* Bottom content */}
      <div style={{ position:'relative', zIndex:1, minHeight:'100vh', display:'flex', flexDirection:'column', justifyContent:'flex-end', padding:'80px 32px 52px', maxWidth:480, margin:'0 auto' }}>

        {/* Top label */}
        <div style={{ position:'absolute', top:88, left:32 }}>
          <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(255,255,255,0.28)', marginBottom:10 }}>Andningsövning</p>
          <div style={{ display:'flex', gap:20 }}>
            {PHASES.map((p, i) => (
              <div key={i} style={{ textAlign:'center' }}>
                <div style={{ fontSize:20, fontWeight:700, color: running && phase === i ? '#fff' : 'rgba(255,255,255,0.25)', lineHeight:1, marginBottom:3, transition:'color .4s' }}>{p.seconds}</div>
                <div style={{ fontFamily:'DM Mono,monospace', fontSize:8, color: running && phase === i ? 'rgba(255,255,255,0.5)' : 'rgba(255,255,255,0.18)', letterSpacing:'0.1em', textTransform:'uppercase', transition:'color .4s' }}>{p.name}</div>
              </div>
            ))}
          </div>
        </div>

        {/* Centre overlay — count */}
        {running && (
          <div style={{ position:'absolute', top:'50%', left:'50%', transform:'translate(-50%, -50%)', textAlign:'center', pointerEvents:'none', zIndex:2 }}>
            <div style={{ fontFamily:'DM Mono,monospace', fontSize:11, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(255,255,255,0.45)', marginBottom:6 }}>{cur.name}</div>
            <div style={{ fontSize:72, fontWeight:700, color:'#fff', lineHeight:1, letterSpacing:'-0.04em' }}>{count}</div>
            <div style={{ fontFamily:'DM Mono,monospace', fontSize:10, color:'rgba(255,255,255,0.3)', marginTop:8 }}>
              Omgång {cycle + 1} / {TOTAL}
            </div>
          </div>
        )}

        {/* Bottom info + start */}
        {running ? (
          <div className="glass" style={{ borderRadius:16, padding:'14px 18px' }}>
            <p style={{ fontSize:13, color:'rgba(255,255,255,0.55)', fontWeight:300 }}>{cur.label}</p>
          </div>
        ) : (
          <div style={{ display:'flex', flexDirection:'column', gap:12 }}>
            <div style={{ display:'flex', alignItems:'baseline', gap:8 }}>
              <h1 style={{ fontSize:'clamp(44px,9vw,68px)', fontWeight:700, letterSpacing:'-0.05em', lineHeight:0.88, color:'#fff' }}>4–7–8</h1>
              <p style={{ fontSize:13, color:'rgba(255,255,255,0.35)', fontWeight:300 }}>andningsövning</p>
            </div>
            <p style={{ fontSize:14, color:'rgba(255,255,255,0.4)', fontWeight:300, marginBottom:8, lineHeight:1.7 }}>
              Aktiverar det parasympatiska nervsystemet och minskar stressnivåer.
            </p>
            <button onClick={start}
              style={{ width:'100%', padding:'16px', borderRadius:100, background:'rgba(255,255,255,0.9)', color:'#13121a', fontSize:14, fontWeight:600 }}>
              Starta
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
